-- name: UpsertAppHTTPRule :one
-- Create or change the settings; status resets to "pending" until the agent reports back through
-- SetAppHTTPRuleStatus.
INSERT INTO app_httprules (app_id, team_id, redirects, headers, basic_auth, access, status, created_by)
VALUES (sqlc.arg('app_id'), sqlc.arg('team_id'), sqlc.arg('redirects'), sqlc.arg('headers'), sqlc.arg('basic_auth'), sqlc.arg('access'), 'pending', sqlc.arg('created_by'))
ON CONFLICT (app_id) DO UPDATE SET redirects = sqlc.arg('redirects'), headers = sqlc.arg('headers'),
    basic_auth = sqlc.arg('basic_auth'), access = sqlc.arg('access'), status = 'pending', error = NULL, updated_at = now()
RETURNING *;

-- name: SetAppHTTPRuleStatus :one
-- The agent's rules.set result: ok on success, error (with the message) on failure.
UPDATE app_httprules SET status = sqlc.arg('status'), error = sqlc.arg('error'), updated_at = now()
WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id')
RETURNING *;

